  test "group names, scopes, depth and node counts are checked" do
    wf = new("w")
    ok = &reserve/2
    one = fn wf -> step(wf, "x#{System.unique_integer([:positive])}", ok) end
    # Each level puts its group at another position, so the generated names differ.
    nest = fn levels ->
      Enum.reduce(1..levels, one, fn i, inner ->
        fn wf -> 1..i |> Enum.reduce(wf, &step(&2, "l#{i}_#{&1}", ok)) |> sequence(inner) end
      end)
