          {fn -> parallel(wf, fn wf -> parallel(wf, one) end) end,
           "parallel_1: the name generated"},
          {fn -> parallel(wf, & &1) end, "no nodes"},
          {fn -> parallel(wf, fn _ -> :ok end) end, "must return"},
          {fn -> sequence(wf, nest.(7)) end, "8 levels"},
          {fn -> scope(wf, "a", &scope(&1, "b", one)) end, "do not nest"},
          {fn -> scope(wf, "a", [non_cancellable: true, timeout_ms: 5], one) end,
