           "only read the input"}
        ] do
      assert_raise ArgumentError, ~r/#{says}/, bad
    end

    assert step(wf, "b", ok, gate: gate("old", max: 0))
    assert step(wf, "b", ok, gate: gate("fmt", min: 2))
    assert input(1_000_000).expr == "${input.1000000}"

    assert %{"input" => %{"k80" => "${input.k80}"}} =
             to_blueprint(child(wf, "c", "other", input: keys)) |> nested()
  end

  defp nested(blueprint), do: List.last(blueprint["nodes"])

  test "node names without dots, module names for non_retryable, a child given as a workflow, known updates" do
    ok = &reserve/2
    wf = new("w") |> step("a", ok)
    invoicing = new("invoicing.v2")

    for {bad, says} <- [
          {fn -> step(wf, "a.b", ok) end, "node"},
          {fn -> retry(non_retryable: [:"Elixir.lower.case"]) end, "module name"},
          {fn -> retry(non_retryable: [:erlang_atom]) end, "module name"},
          {fn -> wf |> update("u", result: ref("updates.other")) |> to_blueprint() end,
           "update other, not declared"},
          {fn -> step(wf, "b", ok, after: Enum.map(1..65, fn _ -> "a" end)) end, "64"},
          {fn -> child(wf, "c", "x", input: Map.new(1..101, &{"k#{&1}", input()})) end,
           "100 keys"},
          {fn -> child(wf, "c", "x", input: List.duplicate(input(), 101)) end, "100 items"}
        ] do
      assert_raise ArgumentError, ~r/#{says}/, bad
    end

    assert retry(non_retryable: [Shop.OutOfStock]) |> elem(1) |> Map.fetch!("non_retryable") == [
             "Shop.OutOfStock"
           ]

    assert %{"workflow" => "invoicing.v2"} =
             wf |> child("c", invoicing) |> to_blueprint() |> nested()

    both = wf |> update("u", result: ref("updates.v")) |> update("v", ok) |> to_blueprint()
    assert both["updates"]["u"] == %{"result" => "${updates.v}"}
  end
end
